$uuid='12345678-1234-1234-1234-123456789abc';$record=PlanningSource::record('post',['id'=>1,'title'=>'Hello','body'=>'<p>Source body</p>','slug'=>'hello','status'=>'publish','date'=>'2025-03-01 10:00:00','author'=>'7'],['meta:rating'=>'4.5']);
$inv=PlanningSource::inventory([$record],[['id'=>'7','email'=>'user@example.com']]);$rule=['types'=>['post'=>['target'=>'articles','fields'=>['data:body'=>['from'=>'body'],'data:rating'=>['from'=>'meta:rating','transform'=>'number'],'data:date'=>['from'=>'date','transform'=>'date']]]],'statuses'=>['publish'=>'published'],'users'=>['7'=>$uuid],'locale'=>'ru','conflict'=>'fail'];$types=['articles'=>$type];$targetUsers=[$uuid=>['id'=>$uuid,'status'=>'active']];$none=fn($email)=>null;
$plan=MigrationPlanner::build($inv,$rule,$types,[],$targetUsers,$none);check($plan['approvable']&&$plan['counts']['create']===1&&$plan['records'][0]['author_id']===$uuid,'real normalized create and explicit user link');
