$m=$rule;$m['users']=[];$p=MigrationPlanner::build($inv,$m,$types,[],$targetUsers,fn($e)=>['id'=>$uuid]);check($p['user_counts']['conflict']===1&&!$p['approvable'],'email collision requires explicit mapping');
$m['users']=['7'=>'create'];$p=MigrationPlanner::build($inv,$m,$types,[],$targetUsers,$none);check($p['user_counts']['create']===1&&$p['approvable'],'new account planning without creation');
$m=$rule;$m['types']['post']['fields']['data:rating']['from']='body';$p=MigrationPlanner::build($inv,$m,$types,[],$targetUsers,$none);check($p['counts']['invalid']===1&&!$p['approvable'],'invalid conversion rejected');
$m=$rule;unset($m['types']['post']['fields']['data:body']);$p=MigrationPlanner::build($inv,$m,$types,[],$targetUsers,$none);check($p['counts']['invalid']===1,'required target field validated');
