$second=$record;$second['id']='2';$p=MigrationPlanner::build(PlanningSource::inventory([$record,$second],$inv['users']),$rule,$types,[],$targetUsers,$none);check($p['counts']['conflict']===1,'duplicate planned slug blocked');
