$work=sys_get_temp_dir().'/ce-plan-'.bin2hex(random_bytes(8));mkdir($work,0700);mkdir($work.'/config');foreach(glob($root.'/config/*.php') as $f)copy($f,$work.'/config/'.basename($f));putenv('CONTENT_STORAGE=file');putenv('CMS_STORAGE=file');putenv('MIGRATION_HTTP_ALLOWED_HOSTS=old.example.com');
