try{$db=new DatabaseManager(new ConfigRepository($work));$tr=new ContentTypeRepository($work,$db);$er=new ContentEntryRepository($work,$db);$tr->create(['handle'=>'articles','name'=>'Articles','fields'=>[['handle'=>'body','label'=>'Body','type'=>'richtext','required'=>true]]]);$vault=new SecretVault('base64:'.base64_encode(random_bytes(32)));$center=new MigrationCenter($work,$vault,new SourceDiscovery($http),planner:new MigrationPlanner($tr,$er,new UserRepository($db,new RoleRepository($db))));
